INSERT INTO public.campaigns (title, slug, description, story, cover_image, goal_amount, raised_amount, donor_count, currency, category, organizer_name, organizer_relation, beneficiary, location, status, verified)
VALUES (
 'ساعدوا عائلة أحمد على تجاوز محنتهم',
 'aidez-famille-ahmed',
 'حملة تضامنية لمساعدة عائلة أحمد على إعادة بناء منزلها بعد الحريق الذي أتى على كل ما تملك.',
 E'قبل أسابيع قليلة، فقدت عائلة أحمد كل شيء في حريق مفاجئ التهم منزلها المتواضع في ضواحي البليدة. نجا الجميع بأعجوبة، لكن لم يبقَ من البيت سوى جدران متفحّمة.\n\n## من هي العائلة؟\n\nأحمد أب لثلاثة أطفال، يعمل حرفياً بسيطاً ويعتمد على دخل يومي متواضع. زوجته سميرة تعتني بالأطفال، أصغرهم في الرابعة من عمره. اليوم تعيش العائلة كلها في غرفة واحدة عند الأقارب، بلا أثاث ولا لوازم أساسية.\n\n## إلى أين يذهب تبرعك؟\n\n- إعادة ترميم السقف والجدران المتضررة\n- شراء الأثاث الأساسي والأفرشة\n- تجهيز الأطفال بالملابس واللوازم المدرسية\n- تغطية مصاريف المعيشة لثلاثة أشهر\n\n## التزامنا تجاهكم\n\nكل دينار يصل إلى العائلة مباشرة، ويتم توثيق المصاريف بالفواتير والصور ونشرها في تحديثات الحملة. لن يُستعمل أي مبلغ خارج ما ذُكر أعلاه.\n\nمساهمتكم، مهما كانت صغيرة، تعيد لهذه العائلة سقفاً وأماناً. وإن لم تستطع التبرع، فمشاركة الحملة وحدها تصنع فرقاً حقيقياً.',
 '',
 3500000, 0, 0, 'DZD', 'عائلات', 'سارة بن أحمد', 'ابنة العائلة', 'عائلة أحمد بن يوسف', 'البليدة، الجزائر', 'published', true
);